def fetch_data_es(kb_base_ids: List[str], nodeUidList: List[str], size: int = ES_SIZE, **ES_CONFIG) -> Optional[Dict]:
    """
    从Elasticsearch获取数据，确保精确匹配knowledgeBaseId和nodeUid。

    Args:
        query: 查询文本
        kb_base_ids: 知识库ID列表
        nodeUidList: 节点UID列表
        size: 返回结果数量
        **ES_CONFIG: 其他参数，可覆盖ES配置

    Returns:
        Optional[Dict]: ES查询结果，如果失败则返回None
    """
    # 初始化ES客户端（保持不变）
    if not es_client:
        es_config = {
            'AI_HOST': kwargs.get('AI_HOST', self.es_config.get('AI_HOST')),
            'AI_USERNAME': kwargs.get('AI_USERNAME', self.es_config.get('AI_USERNAME')),
            'AI_PASSWORD': kwargs.get('AI_PASSWORD', self.es_config.get('AI_PASSWORD')),
            'AI_PORT': kwargs.get('AI_PORT', self.es_config.get('AI_PORT'))
        }
        self.es_client = Elasticsearch(
            hosts=es_config['AI_HOST'],
            http_auth=(es_config['AI_USERNAME'], es_config['AI_PASSWORD']),
            port=es_config['AI_PORT']
        )
        if not self.es_client.ping():
            self.logger.error("连接Elasticsearch失败!")
            return None

    # 构建包含nodeUidList的查询体
    must_clauses = []

    # 精确匹配knowledgeBaseId列表
    if kb_base_ids:
        must_clauses.append({"terms": {"knowledgeBaseId": kb_base_ids}})

    # 精确匹配nodeUid列表
    if nodeUidList:
        must_clauses.append({"terms": {"nodeUid": nodeUidList}})

    query_body = {
        "query": {
            "bool": {
                "must": must_clauses
            }
        }
    }

    # 执行查询（保持不变）
    es_index = kwargs.get('AI_INDEX', self.es_config.get('AI_INDEX'))
    try:
        response = self.es_client.search(index=es_index, body=query_body, size=size)
        return response
    except Exception as e:
        self.logger.exception("Elasticsearch查询异常")
        return None
